from z3 import *

# Enumerations
names = {"Arnold": 0, "Eric": 1}
hairs = {"brown": 0, "black": 1}
flowers = {"daffodils": 0, "carnations": 1}

# Variables for each house (0 = House 1, 1 = House 2)
name = [Int(f"name_{i}") for i in range(2)]
hair = [Int(f"hair_{i}") for i in range(2)]
flower = [Int(f"flower_{i}") for i in range(2)]

s = Solver()

# Domain constraints
for i in range(2):
    s.add(And(name[i] >= 0, name[i] <= 1))
    s.add(And(hair[i] >= 0, hair[i] <= 1))
    s.add(And(flower[i] >= 0, flower[i] <= 1))

# All-different within each attribute category
s.add(Distinct(name[0], name[1]))
s.add(Distinct(hair[0], hair[1]))
s.add(Distinct(flower[0], flower[1]))

# Clue 1: daffodils in the first house (index 0)
s.add(flower[0] == flowers["daffodils"])

# Clue 2: Eric is somewhere to the right of the person with brown hair
for i in range(2):
    for j in range(2):
        s.add(Implies(And(name[i] == names["Eric"], hair[j] == hairs["brown"]), i > j))

# Solve
if s.check() == sat:
    m = s.model()
    # Helper to translate back to strings
    inv_names = {v: k for k, v in names.items()}
    inv_hairs = {v: k for k, v in hairs.items()}
    inv_flowers = {v: k for k, v in flowers.items()}
    for idx in range(2):
        house_num = idx + 1
        n = inv_names[m[name[idx]].as_long()]
        h = inv_hairs[m[hair[idx]].as_long()]
        f = inv_flowers[m[flower[idx]].as_long()]
        print(f"House {house_num}: {n}, {h}, {f}")
else:
    print("No solution found")
